namespace PerformanceAnalysis.Core.Models;

public sealed class SessionMetadata
{
    public int SchemaVersion { get; set; } = 1;

    public string SessionKey { get; set; } = string.Empty;

    public string SourceFolderName { get; set; } = string.Empty;

    /// <summary>
    /// recorder = written by the recorder; derived = generated by the analyzer from ref.txt/CSV.
    /// </summary>
    public string? Source { get; set; }

    public string? DeviceId { get; set; }

    public string? DeviceName { get; set; }

    public string? Alias { get; set; }

    public bool IsBaseline { get; set; }

    /// <summary>
    /// True when the user manually moved/split this session into another device group.
    /// In that case the metadata device name is authoritative, even if it is "未識別裝置".
    /// </summary>
    public bool DeviceOverridden { get; set; }

    public string? Notes { get; set; }

    public DateTimeOffset? StartTime { get; set; }

    public DateTimeOffset? EndTime { get; set; }

    public string? Mode { get; set; }

    public List<string> Tasks { get; set; } = new();

    public HardwareInfo? Hardware { get; set; }

    public List<string> Labels { get; set; } = new();

    public DateTimeOffset? UpdatedAt { get; set; }
}

public sealed class HardwareInfo
{
    public string? Cpu { get; set; }

    public int? Cores { get; set; }

    public int? LogicalCpus { get; set; }

    public double? RamGB { get; set; }

    public string? RamSpeed { get; set; }

    public string? OsName { get; set; }

    public string? OsVersion { get; set; }

    public string? OsBuild { get; set; }

    public string? Gpu { get; set; }
}
